import{_ as t,c as a,o as s,a3 as o}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Pages","description":"","frontmatter":{},"headers":[],"relativePath":"master/website/pages/index.md","filePath":"master/website/pages/index.md","lastUpdated":1793074831000}'),r={name:"master/website/pages/index.md"};function i(n,e,l,h,d,c){return s(),a("div",null,e[0]||(e[0]=[o('<h1 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h1><p>Pages are the fixed parts of your website. Think of About Us, Our Services, Contact Us or FAQ. Unlike blog posts, they do not change often and they are not sorted by date. Visitors reach them from the top bar, the footer or a direct link.</p><blockquote><p><strong>In simple words:</strong> A page is a standing sheet of information. You write it once, choose where its link appears, then publish it.</p></blockquote><p>Open <code>Website → Pages</code>.</p><h2 id="what-you-will-learn" tabindex="-1">What you will learn <a class="header-anchor" href="#what-you-will-learn" aria-label="Permalink to &quot;What you will learn&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it teaches</th></tr></thead><tbody><tr><td><a href="./create-a-page.html">Create a page</a></td><td>The list, the form, the content editor, SEO fields and the header and footer menu switches.</td></tr><tr><td><a href="./publish-and-draft.html">Publish and draft</a></td><td>How a page goes live, how to hide it again, archive, restore, delete and translate.</td></tr></tbody></table><h2 id="how-a-page-reaches-the-visitor" tabindex="-1">How a page reaches the visitor <a class="header-anchor" href="#how-a-page-reaches-the-visitor" aria-label="Permalink to &quot;How a page reaches the visitor&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>New Page → Draft → Publish → /pages/{slug} is live → link in header or footer menu</span></span></code></pre></div><ol><li>You fill in the form. The page starts as a <strong>draft</strong>.</li><li>You click <strong>Publish</strong>. Visitors can now open it.</li><li>The menu switches decide where the link shows.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The page with the slug <code>home</code> is your home page. Visitors see it at <code>/</code>, not at <code>/pages/home</code>.</p></div><h2 id="pages-that-already-exist" tabindex="-1">Pages that already exist <a class="header-anchor" href="#pages-that-already-exist" aria-label="Permalink to &quot;Pages that already exist&quot;">​</a></h2><p>A fresh site has these pages: <strong>Home</strong>, <strong>About Us</strong>, <strong>Privacy Policy</strong>, <strong>Terms &amp; Conditions</strong>, <strong>News &amp; Announcements</strong>, <strong>Our Services</strong>, <strong>Contact Us</strong>, <strong>Careers</strong> and <strong>FAQ</strong>. Edit them instead of starting from nothing.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Website overview</a></li><li><a href="./../blog/blog-posts.html">Blog posts</a></li><li><a href="./../settings/manage-contacts.html">Manage contacts</a></li></ul>',14)]))}const u=t(r,[["render",i]]);export{p as __pageData,u as default};
